<template><div class="page"><div class="page-head"><div><h2>投诉数据</h2><p>客户声音用于风险根因分析，可与SLA、重复投诉和流失风险联动。</p></div><div><el-input-number v-model="filter.companyId" :min="1" style="width:120px;margin-right:8px"/><el-input v-model="filter.category" placeholder="投诉类别" style="width:150px;margin-right:8px"/><el-button @click="load">查询</el-button><el-button type="primary" v-if="auth.has('complaint:write')" @click="visible=true">新增投诉</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="complaintNo" label="编号" width="170"/><el-table-column prop="complaintDate" label="日期" width="110"/><el-table-column prop="companyId" label="企业ID" width="80"/><el-table-column prop="productName" label="产品" min-width="150"/><el-table-column prop="category" label="类别"/><el-table-column prop="severity" label="等级" width="70"/><el-table-column prop="description" label="描述" min-width="250" show-overflow-tooltip/><el-table-column prop="slaExceeded" label="超SLA" width="80"><template #default="s"><el-tag :type="s.row.slaExceeded?'danger':'success'">{{s.row.slaExceeded?'是':'否'}}</el-tag></template></el-table-column><el-table-column prop="rootCause" label="根因"/><el-table-column prop="churnRisk" label="流失风险"/><el-table-column prop="status" label="状态"/></el-table>
<el-dialog v-model="visible" title="新增投诉" width="620px"><el-form label-width="95px"><el-row :gutter="12"><el-col :span="12"><el-form-item label="企业ID"><el-input-number v-model="form.companyId" :min="1"/></el-form-item></el-col><el-col :span="12"><el-form-item label="投诉日期"><el-date-picker v-model="form.complaintDate" value-format="YYYY-MM-DD"/></el-form-item></el-col></el-row><el-form-item label="客户名称"><el-input v-model="form.customerName"/></el-form-item><el-form-item label="产品"><el-input v-model="form.productName"/></el-form-item><el-form-item label="投诉类别"><el-input v-model="form.category"/></el-form-item><el-form-item label="投诉描述"><el-input type="textarea" :rows="3" v-model="form.description"/></el-form-item><el-row :gutter="12"><el-col :span="8"><el-form-item label="严重度"><el-select v-model="form.severity"><el-option v-for="x in ['P1','P2','P3','P4']" :key="x" :value="x"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="响应分钟"><el-input-number v-model="form.firstResponseMinutes"/></el-form-item></el-col><el-col :span="8"><el-form-item label="解决小时"><el-input-number v-model="form.solveHours" :precision="1"/></el-form-item></el-col></el-row><el-form-item label="根因"><el-input v-model="form.rootCause"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore();const rows=ref([]),loading=ref(false),visible=ref(false),filter=ref({companyId:null,category:''});const form=ref({companyId:1,complaintDate:new Date().toISOString().slice(0,10),customerName:'示例客户',productName:'核心产品',category:'客服响应',description:'客户反馈处理进度不透明，希望尽快给出明确方案。',severity:'P2',repeatFlag:0,firstResponseMinutes:35,solveHours:8,slaExceeded:1,rootCause:'响应流程待优化',churnRisk:'中',satisfaction:3,status:'处理中'});async function load(){loading.value=true;try{let p={...filter.value};if(!p.companyId)delete p.companyId;if(!p.category)delete p.category;rows.value=(await api.complaints(p))||[]}finally{loading.value=false}}async function save(){await api.createComplaint(form.value);ElMessage.success('投诉已保存');visible.value=false;load()}onMounted(load)</script>
